shell_commands:
node -e "
import('@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js').then(m => {
  const fs = await import('node:fs');
  const content = fs.readFileSync('specs/hal-engine-config-hooks/spec.md', 'utf8');
  const links = m.linksForStatements(content);
  const relevant = links.filter(s => s.testLinks.length > 0 && s.statement.text.includes('addUsage'));
  console.log(JSON.stringify(relevant.map(s => ({text: s.statement.text.slice(0,80), links: s.testLinks})), null, 2));
});
"
# Use node --input-type=module approach
node --input-type=module <<'EOF'
import { linksForStatements } from '@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js';
import { readFileSync } from 'node:fs';
const content = readFileSync('specs/hal-engine-config-hooks/spec.md', 'utf8');
const links = linksForStatements(content);
const relevant = links.filter(s => s.testLinks.length > 0 && s.statement.text.includes('addUsage'));
console.log(JSON.stringify(relevant.map(s => ({text: s.statement.text.slice(0,80), links: s.testLinks})), null, 2));
EOF
